names={v:k for k,v in globals().items() if k.isupper() and isinstance(v,int) and 1<=v<=25 and k in ("KICK","SNARE","CLAP","HATC","HATO","CRASH","TOM","BASS","LEADP","LEADS","PADMIN","PADMAJ","STABMIN","STABMAJ","PLUCK","ARPL","ARPR","BELL","RISER","REVC","ACID","ECHO","SAWECHO","LEADSR","SHAKER")}
