# effects used
fx={}
for c in S.cells.values():
    if c.fx or c.fxp: fx[(c.fx)]=fx.get(c.fx,0)+1
print("effect types used (0=arp,2=porta down,8=pan,0xE=extended,0x14=key off):",{hex(k):v for k,v in sorted(fx.items())})
print("cells:",len(S.cells))
EOF"}

